package io.github.miklires.mclans.storage;

import io.github.miklires.mclans.api.ClanMemberView;import io.github.miklires.mclans.api.ClanRole;import io.github.miklires.mclans.api.ClanView;import java.nio.file.Files;import java.nio.file.Path;import java.sql.*;import java.time.Instant;import java.util.*;import java.util.concurrent.*;
public final class ClanRepository implements AutoCloseable {
 private final String jdbcUrl;private final ExecutorService executor=Executors.newSingleThreadExecutor(Thread.ofVirtual().name("mclans-db-",0).factory());
 public ClanRepository(Path file){this(prepareUrl(file));}ClanRepository(String url){jdbcUrl=url;try{Class.forName("org.h2.Driver");migrate();}catch(Exception e){throw new IllegalStateException("Cannot initialize mClans storage",e);}}
 private static String prepareUrl(Path file){try{Files.createDirectories(file.toAbsolutePath().getParent());}catch(java.io.IOException e){throw new IllegalStateException(e);}return "jdbc:h2:file:"+file.toAbsolutePath().toString().replace('\\','/')+";AUTO_SERVER=TRUE";}
 private Connection connection()throws SQLException{return DriverManager.getConnection(jdbcUrl,"sa","");}
 private void migrate()throws SQLException{try(Connection c=connection();Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS schema_version(version INT PRIMARY KEY)");s.executeUpdate("MERGE INTO schema_version(version) KEY(version) VALUES(1)");s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR_IGNORECASE(16) NOT NULL UNIQUE,tag VARCHAR_IGNORECASE(5) NOT NULL UNIQUE,level INT NOT NULL DEFAULT 1,points BIGINT NOT NULL DEFAULT 0,bank BIGINT NOT NULL DEFAULT 0,friendly_fire BOOLEAN NOT NULL DEFAULT FALSE,owner_id UUID NOT NULL,created_at BIGINT NOT NULL)
 """);s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clan_members(player_id UUID PRIMARY KEY,player_name VARCHAR(32) NOT NULL,clan_id BIGINT NOT NULL,role VARCHAR(16) NOT NULL,joined_at BIGINT NOT NULL,FOREIGN KEY(clan_id) REFERENCES clans(id) ON DELETE CASCADE)
 """);s.executeUpdate("CREATE INDEX IF NOT EXISTS clan_members_clan_idx ON clan_members(clan_id)");s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clan_invites(clan_id BIGINT NOT NULL,target_id UUID NOT NULL,target_name VARCHAR(32) NOT NULL,inviter_id UUID NOT NULL,expires_at BIGINT NOT NULL,PRIMARY KEY(clan_id,target_id),FOREIGN KEY(clan_id) REFERENCES clans(id) ON DELETE CASCADE)
 """);s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clan_ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,clan_id BIGINT NOT NULL,actor_id UUID NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT NOT NULL,reason VARCHAR(100) NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(clan_id) REFERENCES clans(id) ON DELETE CASCADE)
 """);s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS pvp_awards(killer_id UUID NOT NULL,victim_id UUID NOT NULL,last_awarded BIGINT NOT NULL,PRIMARY KEY(killer_id,victim_id))
 """);s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clan_relations(first_clan BIGINT NOT NULL,second_clan BIGINT NOT NULL,status VARCHAR(16) NOT NULL,requested_by BIGINT NOT NULL,updated_at BIGINT NOT NULL,PRIMARY KEY(first_clan,second_clan),FOREIGN KEY(first_clan) REFERENCES clans(id) ON DELETE CASCADE,FOREIGN KEY(second_clan) REFERENCES clans(id) ON DELETE CASCADE)
 """);s.executeUpdate("""
 CREATE TABLE IF NOT EXISTS clan_homes(clan_id BIGINT PRIMARY KEY,world_id UUID NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,yaw REAL NOT NULL,pitch REAL NOT NULL,updated_by UUID NOT NULL,updated_at BIGINT NOT NULL,FOREIGN KEY(clan_id) REFERENCES clans(id) ON DELETE CASCADE)
 """);s.executeUpdate("MERGE INTO schema_version(version) KEY(version) VALUES(2)");}}
 public CompletableFuture<ClanView> create(UUID owner,String ownerName,String name,String tag){return task(()->{try(Connection c=connection()){c.setAutoCommit(false);try{if(member(c,owner).isPresent())throw new ClanConflictException("Player already belongs to a clan");long now=Instant.now().toEpochMilli(),id;try(PreparedStatement s=c.prepareStatement("INSERT INTO clans(name,tag,owner_id,created_at) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,name);s.setString(2,tag);s.setObject(3,owner);s.setLong(4,now);s.executeUpdate();try(ResultSet keys=s.getGeneratedKeys()){keys.next();id=keys.getLong(1);}}try(PreparedStatement s=c.prepareStatement("INSERT INTO clan_members(player_id,player_name,clan_id,role,joined_at) VALUES(?,?,?,'OWNER',?)")){s.setObject(1,owner);s.setString(2,ownerName);s.setLong(3,id);s.setLong(4,now);s.executeUpdate();}ClanView clan=findClan(c,id).orElseThrow();c.commit();return clan;}catch(Throwable t){c.rollback();if(t instanceof SQLException e&&"23505".equals(e.getSQLState()))throw new ClanConflictException("Clan name or tag is already used");throw t;}}});}
 public CompletableFuture<Optional<ClanView>> clanOf(UUID player){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT c.*,COUNT(m2.player_id) member_count FROM clan_members m JOIN clans c ON c.id=m.clan_id JOIN clan_members m2 ON m2.clan_id=c.id WHERE m.player_id=? GROUP BY c.id")){s.setObject(1,player);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapClan(r)):Optional.empty();}}});}
 public CompletableFuture<Optional<ClanView>> findClan(String nameOrTag){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT c.*,COUNT(m.player_id) member_count FROM clans c LEFT JOIN clan_members m ON m.clan_id=c.id WHERE c.name=? OR c.tag=? GROUP BY c.id")){s.setString(1,nameOrTag);s.setString(2,nameOrTag);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapClan(r)):Optional.empty();}}});}
 public CompletableFuture<Optional<ClanMemberView>> member(UUID player){return task(()->{try(Connection c=connection()){return member(c,player);}});}
 public CompletableFuture<List<ClanMemberView>> members(long clanId){return task(()->{List<ClanMemberView> out=new ArrayList<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT player_id,player_name,role,joined_at FROM clan_members WHERE clan_id=? ORDER BY CASE role WHEN 'OWNER' THEN 0 WHEN 'OFFICER' THEN 1 ELSE 2 END,joined_at")){s.setLong(1,clanId);try(ResultSet r=s.executeQuery()){while(r.next())out.add(mapMember(r));}}return List.copyOf(out);});}
 public CompletableFuture<Void> invite(long clanId,UUID target,String targetName,UUID inviter,long expiresAt){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("MERGE INTO clan_invites(clan_id,target_id,target_name,inviter_id,expires_at) KEY(clan_id,target_id) VALUES(?,?,?,?,?)")){s.setLong(1,clanId);s.setObject(2,target);s.setString(3,targetName);s.setObject(4,inviter);s.setLong(5,expiresAt);s.executeUpdate();}return null;});}
 public CompletableFuture<Boolean> acceptInvite(UUID target,String targetName,long clanId,int memberLimit){return task(()->{try(Connection c=connection()){c.setAutoCommit(false);try{if(member(c,target).isPresent()){c.rollback();return false;}long now=Instant.now().toEpochMilli();try(PreparedStatement lock=c.prepareStatement("SELECT expires_at FROM clan_invites WHERE clan_id=? AND target_id=? FOR UPDATE")){lock.setLong(1,clanId);lock.setObject(2,target);try(ResultSet r=lock.executeQuery()){if(!r.next()||r.getLong(1)<now){c.rollback();return false;}}}int count;try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM clan_members WHERE clan_id=?")){s.setLong(1,clanId);try(ResultSet r=s.executeQuery()){r.next();count=r.getInt(1);}}if(count>=memberLimit){c.rollback();return false;}try(PreparedStatement s=c.prepareStatement("INSERT INTO clan_members(player_id,player_name,clan_id,role,joined_at) VALUES(?,?,?,'MEMBER',?)")){s.setObject(1,target);s.setString(2,targetName);s.setLong(3,clanId);s.setLong(4,now);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("DELETE FROM clan_invites WHERE target_id=?")){s.setObject(1,target);s.executeUpdate();}c.commit();return true;}catch(Throwable t){c.rollback();throw t;}}});}
 public CompletableFuture<Boolean> leave(UUID player){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("DELETE FROM clan_members WHERE player_id=? AND role<>'OWNER'")){s.setObject(1,player);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> removeMember(long clanId,UUID player){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("DELETE FROM clan_members WHERE clan_id=? AND player_id=? AND role<>'OWNER'")){s.setLong(1,clanId);s.setObject(2,player);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> setRole(long clanId,UUID player,ClanRole role){if(role==ClanRole.OWNER)throw new IllegalArgumentException("Use ownership transfer");return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("UPDATE clan_members SET role=? WHERE clan_id=? AND player_id=? AND role<>'OWNER'")){s.setString(1,role.name());s.setLong(2,clanId);s.setObject(3,player);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> transferOwnership(long clanId,UUID currentOwner,UUID newOwner){return task(()->{try(Connection c=connection()){c.setAutoCommit(false);try{int changed;try(PreparedStatement s=c.prepareStatement("UPDATE clans SET owner_id=? WHERE id=? AND owner_id=?")){s.setObject(1,newOwner);s.setLong(2,clanId);s.setObject(3,currentOwner);changed=s.executeUpdate();}if(changed!=1){c.rollback();return false;}try(PreparedStatement s=c.prepareStatement("UPDATE clan_members SET role=CASE WHEN player_id=? THEN 'OWNER' WHEN player_id=? THEN 'OFFICER' ELSE role END WHERE clan_id=? AND player_id IN (?,?)")){s.setObject(1,newOwner);s.setObject(2,currentOwner);s.setLong(3,clanId);s.setObject(4,newOwner);s.setObject(5,currentOwner);if(s.executeUpdate()!=2){c.rollback();return false;}}c.commit();return true;}catch(Throwable t){c.rollback();throw t;}}});}
 public CompletableFuture<Optional<ClanMemberView>> memberByName(long clanId,String name){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT player_id,player_name,role,joined_at FROM clan_members WHERE clan_id=? AND LOWER(player_name)=LOWER(?)")){s.setLong(1,clanId);s.setString(2,name);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapMember(r)):Optional.empty();}}});}
 public CompletableFuture<Boolean> disband(long clanId,UUID owner){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("DELETE FROM clans WHERE id=? AND owner_id=?")){s.setLong(1,clanId);s.setObject(2,owner);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> setFriendlyFire(long clanId,UUID owner,boolean enabled){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("UPDATE clans SET friendly_fire=? WHERE id=? AND owner_id=?")){s.setBoolean(1,enabled);s.setLong(2,clanId);s.setObject(3,owner);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> awardKill(long clanId,UUID killer,UUID victim,long points,long cooldownMillis,int newLevel){return task(()->{long now=Instant.now().toEpochMilli();try(Connection c=connection()){c.setAutoCommit(false);try{long previous=0;try(PreparedStatement s=c.prepareStatement("SELECT last_awarded FROM pvp_awards WHERE killer_id=? AND victim_id=? FOR UPDATE")){s.setObject(1,killer);s.setObject(2,victim);try(ResultSet r=s.executeQuery()){if(r.next())previous=r.getLong(1);}}if(previous>now-cooldownMillis){c.rollback();return false;}try(PreparedStatement s=c.prepareStatement("MERGE INTO pvp_awards(killer_id,victim_id,last_awarded) KEY(killer_id,victim_id) VALUES(?,?,?)")){s.setObject(1,killer);s.setObject(2,victim);s.setLong(3,now);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("UPDATE clans SET points=CASE WHEN points>? THEN ? ELSE points+? END,level=GREATEST(level,?) WHERE id=?")){s.setLong(1,Long.MAX_VALUE-points);s.setLong(2,Long.MAX_VALUE);s.setLong(3,points);s.setInt(4,newLevel);s.setLong(5,clanId);s.executeUpdate();}c.commit();return true;}catch(Throwable t){c.rollback();throw t;}}});}
 public CompletableFuture<Boolean> changeBank(long clanId,UUID actor,long delta,String reason){return task(()->{long now=Instant.now().toEpochMilli();try(Connection c=connection()){c.setAutoCommit(false);try{long balance;try(PreparedStatement s=c.prepareStatement("SELECT bank FROM clans WHERE id=? FOR UPDATE")){s.setLong(1,clanId);try(ResultSet r=s.executeQuery()){if(!r.next()){c.rollback();return false;}balance=r.getLong(1);}}long next=Math.addExact(balance,delta);if(next<0){c.rollback();return false;}try(PreparedStatement s=c.prepareStatement("UPDATE clans SET bank=? WHERE id=?")){s.setLong(1,next);s.setLong(2,clanId);s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("INSERT INTO clan_ledger(clan_id,actor_id,amount,balance_after,reason,created_at) VALUES(?,?,?,?,?,?)")){s.setLong(1,clanId);s.setObject(2,actor);s.setLong(3,delta);s.setLong(4,next);s.setString(5,reason);s.setLong(6,now);s.executeUpdate();}c.commit();return true;}catch(Throwable t){c.rollback();throw t;}}});}
 public CompletableFuture<List<ClanView>> top(int limit){return task(()->{List<ClanView> out=new ArrayList<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT c.*,COUNT(m.player_id) member_count FROM clans c LEFT JOIN clan_members m ON m.clan_id=c.id GROUP BY c.id ORDER BY c.points DESC,c.level DESC,c.created_at ASC LIMIT ?")){s.setInt(1,Math.clamp(limit,1,100));try(ResultSet r=s.executeQuery()){while(r.next())out.add(mapClan(r));}}return List.copyOf(out);});}
 public CompletableFuture<Boolean> setHome(long clanId,UUID actor,UUID world,double x,double y,double z,float yaw,float pitch){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("MERGE INTO clan_homes(clan_id,world_id,x,y,z,yaw,pitch,updated_by,updated_at) KEY(clan_id) VALUES(?,?,?,?,?,?,?,?,?)")){s.setLong(1,clanId);s.setObject(2,world);s.setDouble(3,x);s.setDouble(4,y);s.setDouble(5,z);s.setFloat(6,yaw);s.setFloat(7,pitch);s.setObject(8,actor);s.setLong(9,Instant.now().toEpochMilli());return s.executeUpdate()==1;}});}
 public CompletableFuture<Optional<ClanHome>> home(long clanId){return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT world_id,x,y,z,yaw,pitch FROM clan_homes WHERE clan_id=?")){s.setLong(1,clanId);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(new ClanHome(r.getObject(1,UUID.class),r.getDouble(2),r.getDouble(3),r.getDouble(4),r.getFloat(5),r.getFloat(6))):Optional.empty();}}});}
 public CompletableFuture<RelationResult> requestAlliance(long actor,long target){return relation(actor,target,true);}
 public CompletableFuture<RelationResult> setEnemy(long actor,long target){return relation(actor,target,false);}
 private CompletableFuture<RelationResult> relation(long actor,long target,boolean alliance){if(actor==target)return CompletableFuture.completedFuture(RelationResult.REJECTED);return task(()->{long first=Math.min(actor,target),second=Math.max(actor,target),now=Instant.now().toEpochMilli();try(Connection c=connection()){c.setAutoCommit(false);try{String status=null;long requested=0;try(PreparedStatement s=c.prepareStatement("SELECT status,requested_by FROM clan_relations WHERE first_clan=? AND second_clan=? FOR UPDATE")){s.setLong(1,first);s.setLong(2,second);try(ResultSet r=s.executeQuery()){if(r.next()){status=r.getString(1);requested=r.getLong(2);}}}String next;RelationResult result;if(!alliance){next="ENEMY";result=RelationResult.ENEMY;}else if("PENDING".equals(status)&&requested!=actor){next="ALLY";result=RelationResult.ALLIED;}else if("ALLY".equals(status)){c.rollback();return RelationResult.ALREADY;}else{next="PENDING";result=RelationResult.REQUESTED;}try(PreparedStatement s=c.prepareStatement("MERGE INTO clan_relations(first_clan,second_clan,status,requested_by,updated_at) KEY(first_clan,second_clan) VALUES(?,?,?,?,?)")){s.setLong(1,first);s.setLong(2,second);s.setString(3,next);s.setLong(4,actor);s.setLong(5,now);s.executeUpdate();}c.commit();return result;}catch(Throwable t){c.rollback();throw t;}}});}
 public CompletableFuture<Boolean> removeRelation(long actor,long target){return task(()->{long first=Math.min(actor,target),second=Math.max(actor,target);try(Connection c=connection();PreparedStatement s=c.prepareStatement("DELETE FROM clan_relations WHERE first_clan=? AND second_clan=?")){s.setLong(1,first);s.setLong(2,second);return s.executeUpdate()==1;}});}
 public CompletableFuture<Boolean> areAllies(long first,long second){if(first==second)return CompletableFuture.completedFuture(true);return task(()->{try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT 1 FROM clan_relations WHERE first_clan=? AND second_clan=? AND status='ALLY'")){s.setLong(1,Math.min(first,second));s.setLong(2,Math.max(first,second));try(ResultSet r=s.executeQuery()){return r.next();}}});}
 public CompletableFuture<Set<ClanPair>> allies(){return task(()->{Set<ClanPair> out=new HashSet<>();try(Connection c=connection();PreparedStatement s=c.prepareStatement("SELECT first_clan,second_clan FROM clan_relations WHERE status='ALLY'");ResultSet r=s.executeQuery()){while(r.next())out.add(new ClanPair(r.getLong(1),r.getLong(2)));}return Set.copyOf(out);});}
 private static Optional<ClanMemberView> member(Connection c,UUID player)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT player_id,player_name,role,joined_at FROM clan_members WHERE player_id=?")){s.setObject(1,player);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapMember(r)):Optional.empty();}}}
 private static Optional<ClanView> findClan(Connection c,long id)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT c.*,COUNT(m.player_id) member_count FROM clans c LEFT JOIN clan_members m ON m.clan_id=c.id WHERE c.id=? GROUP BY c.id")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapClan(r)):Optional.empty();}}}
 private static ClanView mapClan(ResultSet r)throws SQLException{return new ClanView(r.getLong("id"),r.getString("name"),r.getString("tag"),r.getInt("level"),r.getLong("points"),r.getLong("bank"),r.getBoolean("friendly_fire"),r.getInt("member_count"),r.getObject("owner_id",UUID.class),Instant.ofEpochMilli(r.getLong("created_at")));}
 private static ClanMemberView mapMember(ResultSet r)throws SQLException{return new ClanMemberView(r.getObject("player_id",UUID.class),r.getString("player_name"),ClanRole.valueOf(r.getString("role")),Instant.ofEpochMilli(r.getLong("joined_at")));}
 private <T> CompletableFuture<T> task(SqlTask<T> t){return CompletableFuture.supplyAsync(()->{try{return t.run();}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Storage operation failed",e);}},executor);}@Override public void close(){executor.close();}@FunctionalInterface private interface SqlTask<T>{T run()throws Exception;}
 public static final class ClanConflictException extends RuntimeException{public ClanConflictException(String message){super(message);}}
 public record ClanHome(UUID worldId,double x,double y,double z,float yaw,float pitch){}
 public enum RelationResult{REQUESTED,ALLIED,ENEMY,ALREADY,REJECTED}
 public record ClanPair(long first,long second){public ClanPair{if(first>second){long swap=first;first=second;second=swap;}}}
}
